/*作者：lazyalie*/
/*作者有话说:禁二传二改商用。感谢帮助过我的老师们🥺🥺*/
/* 部分代码以及类名来自教程帖以及尾巴老师的拼好码，教程帖指路https://discord.com/channels/1291925535324110879/1380392618336194702;拼好码指路https://discord.com/channels/1291925535324110879/1422717884378910801 */
/* 素材来源花瓣网，小红书: Pipet，壁纸来源小红书: MsM */


@import url("https://fontsapi.zeoseven.com/875/main/result.css");/* "ChillHuoSong_F" */
@import url("https://fontsapi.zeoseven.com/417/main/result.css");/* "TRW UDMincho" */
@import url("https://fontsapi.zeoseven.com/81/main/result.css");/* "QIJIC" */




/* =====全局控制===== */
:root {
  --全局字体:"TRW UDMincho" ;
  --名字字体: "QIJIC"; 
  --头像显示区域:center 30%; /*改数字调整头像到你想看到的部位，感谢咩野老师的代码*/
  --气泡间距: 35cqw;
  --气泡与输入框间距: 50px;
  --输入框内文字: ""; 
  --名字字体大小: 4.5cqw;
  --crimson70a: transparent; 
  --black30a:transparent ;
  --black50a:transparent ;
  --上层气泡宽:100cqw;
  --气泡主体宽:100cqw;
  --下层气泡宽:100cqw;
  --头像大小:35cqw;
  --头像左右:4%;
  --头像上下:22cqw;
  --上气泡高度:82cqw ;
  --下气泡高度:-38.3cqw;
  --名字上下: 49.5cqw;
  --名字左右: 53cqw;
  --时间戳上下:-13cqw;
  --时间戳左右:50cqw ;
  --三元素上下:59cqw; 
   --topbar透明度: 0;/* 由于我觉得这个插件影响美观，所以我隐藏了，如果想要出现，就把这个数字改成1。但是实际上我适配没做好，它非常的难点，还不如不要 */
}
/* =====全局控制结束===== */



/*感谢咩野老师的全局阴影去除*/
body *:not(#send_form,#send_textarea,.mes,q,textarea,input[type="number"],select,#user-settings-block h4,.standoutHeader,.completion_prompt_manager_prompt,img#avatar_load_preview,.menu_button,.mes .mes_block,input[type="checkbox"],#toast-container > .toast,code, pre code.hljs,.character_select.is_fav ,
.avatar-container.interactable.selected,.swipe_left,
.swipe_right,.recentChat.inline-drawer-header ){
  box-shadow: none !important; 
  filter: none!important;
}

body {
    font-family: var(--全局字体);
    font-weight: normal;
}

/*====欢迎页====*/
.recentChatList {
  flex-direction: row !important;
  overflow-x: auto;
  overflow-y: hidden;
  gap: 12px;
  padding: 12px;
  scrollbar-width: none;
}
.recentChatList::-webkit-scrollbar {
  display: none;
}
.chatNameContainer {
  flex-direction: column !important;
  align-items: center !important;
}
.recentChat {
    flex-direction: column !important;
    align-items: center !important;
    min-width: 200px !important;
    max-width: 220px !important;
    flex-shrink: 0 !important;
    padding: 20px !important;  
    background: url('https://iili.io/B49bCrJ.png') no-repeat center/cover;  
    border-radius: 32px 12px 32px 12px !important;
    border: 1px solid rgba(220, 200, 170, 0.6) !important;
    outline: 1px solid rgba(255, 250, 230, 0.8) !important;
    outline-offset: 2px !important;
    box-shadow: 0 12px 28px -8px rgba(80, 50, 25, 0.15),
                inset 0 1px 0 rgba(255, 255, 240, 0.6) !important;  
    color: #7D6345 !important;
    transition: all 0.3s ease-out !important;
  margin-right: 12px;
}

.recentChat .avatar {
  width: 150px !important;
  height: calc(150px * 1.2/1) !important; 
  margin-bottom: -21px!important;
}
.recentChat .avatar img
 {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  border-radius: inherit; 
}
.recentChat .recentChatInfo {
  flex-direction: column !important;
  align-items: center;
  width: 100%;
  overflow: hidden;
}

.recentChat .chatNameContainer,
.recentChat .chatMessageContainer,
.recentChat .chatMessage {
  max-width: 100%;
  word-break: break-all;
  white-space: normal !important;
  text-align: center;
  overflow: hidden;
}


/*========文本调节========*/
.mes .mes_text {
  z-index: 99999!important;
    /* 字符间距  */
    letter-spacing: 1.8px; 
    /*  行间距   */
    line-height: 2 ; 
  text-align: justify !important;  
  width: 100%;
  padding-left: 1px;
  padding-right: 1px;
}
/* 每个段落开头缩进字符 */
p {
  text-indent: 0em; 

}
/*=====全局抽屉=====*/
  body.no-blur .drawer-content.openDrawer{
 background-image: url('https://iili.io/B4H580X.png') !important;
  background-repeat: repeat-y !important;
  background-size: 100% auto !important;
  background-position: top center !important;
    padding: 7px;
    border-radius: none!important;
    margin-top: 12px;
}


/*====顶栏====*/

#extensionTopBar { 
  position: absolute;
     top: 3.2px!important;
  z-index: 999;
  background-color: rgba(255, 255, 255, 1) !important;
    z-index: 1000 !important;
    min-height: 35px !important;
  opacity: var(--topbar透明度);
pointer-events: auto !important;
}

#extensionTopBar,
#extensionTopBar * {
    pointer-events: auto !important;
}
#top-settings-holder {
   background-size: contain !important; 
   min-height: 80px;
  aspect-ratio:15/2.5;
    background: url('https://iili.io/B4CSyvf.png')  left top !important;     
  background-size: auto 100% !important;    
  position: relative !important;
}

#top-settings-holder .drawer-icon {
     opacity: 1!important; 
  content: url("https://iili.io/B4Hz3SR.png");
  width: 20px;    
   transform: rotate(34deg)translateY(-25px);
  z-index: 45!important;
}

#top-settings-holder .drawer-icon.openIcon {
    content: url("https://iili.io/B4Bm5Sp.png") !important;
  width: 70px;
  transform: rotate(-3deg)translateY(-25px);
}


#top-settings-holder::before {
    content: '' !important;
    position: absolute !important;
    top: 0% !important;
    left: 20% !important;
    transform: translate(-50%, -34%) !important;
    width: 45% !important;
    height: 200px !important;
    background: url('https://iili.io/B4C6hx4.png') center center / contain no-repeat !important;
    z-index: 13 !important;
    pointer-events: none !important;
}
/*====底栏====*/
#send_form [class*="fa-"] {
  font-size: 0 !important;
    color: transparent !important;    opacity: 1!important;
  margin: 2px;
  overflow: visible !important;
}

#send_but,
#quick-reply-rocket-button,
#extensionsMenuButton,
#options_button {
    background: url('https://iili.io/B4Hz3SR.png') center/15px no-repeat !important; 

}



/* 感谢nini老师分享的隐藏输入框小黑点 */
#send_textarea {
    resize: none !important;
}

/* 感谢墨千尾老师的输入框内文字自定义 */
#nonQRFormItems {
  position: relative;
}
#send_textarea::placeholder {
  color: rgba(0, 0, 0, 0) !important;
  text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--输入框内文字);
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  color: rgba(55, 47, 32, 0.65);
  font-style: normal;
  font-size: 0.5em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}

#send_textarea {
  background: rgba(255, 255, 253, 1) !important;
  min-height: 30px;
  border: 1px solid rgba(220, 219, 213, 1) !important;
  outline: 1px solid rgba(131, 128, 114, 1) !important;
  outline-offset: 1px !important;
  box-shadow: inset 0 1px 2px rgba(162, 157, 153, 0.04), 0 2px 6px rgba(100, 70, 40, 0.06) !important;
  border-radius: 0 !important;
  resize: none !important;
}

/* 感谢nakari老师的悬浮底栏 */
#sheld, 
#chat {
    height: calc(102dvh + var(--bottomFormBlockSize));
    max-height: calc(102dvh + var(--bottomFormBlockSize));
}

#send_form {  
  background: url('https://iili.io/B49bCrJ.png') center 75% / cover no-repeat !important;
    position: relative;
    width: 95%;
    display: flex !important;
    align-items: center !important;
    padding: 10px 25px !important;
    transition: all 0.3s ease; 
    box-shadow: 0 4px 15px rgba(223, 218, 205, 0.4), inset 0 -2px 5px rgba(232, 231, 228, 0.7) !important;
    border-radius: 0 !important;
    overflow: visible !important;
}


/* 确保输入框固定在底部 */
#form_sheld {
    position: sticky;
    bottom: 70px;
    transition: transform 0.3s ease;
}
/* 感谢nakari老师的输入时输入框占满顶部 */
#nonQRFormItems {
  display: grid !important;
  grid-template-columns: auto 1fr auto !important;
  grid-template-rows: auto auto !important;
  place-items: center !important;
}

#rightSendForm {
  grid-column: 3 / 4 !important;
}

#send_textarea:focus,
#send_textarea:not(:placeholder-shown) {
  grid-row: 1 / 2 !important;
  grid-column: 1 / 4 !important;
  justify-self: center !important;
  width: 97% !important;
}
/* =====弹窗===== */
/* 弹窗背景来自n师 */
.popup[open]::backdrop{
 background-image: url('https://iili.io/B4H580X.png') !important;
  background-repeat: repeat-y !important;
  background-size: 100% auto !important;
  background-position: top center !important;
}
.dialog,
.popup{
background: transparent;
}
.TH-popup .popup,
.vfm .popup {
    padding: 20px !important;
    border-radius: 0 !important;
    background: linear-gradient(180deg, rgba(255, 251, 240, 1) 0%, #ffffff 100%) !important;
    box-shadow: 0 20px 40px rgba(239, 233, 221, 0.25), inset 0 1px 2px rgba(255, 255, 255, 0.8) !important;   
}

/*消息弹窗*/
#toast-container > .toast {
border: 1px solid rgba(217, 207, 190, 1) !important;
outline: 1px solid rgba(240, 231, 218, 1) !important;
outline-offset: 2px !important;
background: url('https://iili.io/B49bCrJ.png') no-repeat center/cover!important;
color: #A0815C !important;
padding: 14px 16px  !important;
cursor: pointer !important;
letter-spacing: 0.5px !important;
box-shadow: 
inset 0 0 0 1px rgba(255, 255, 245, 0.9),
inset 0 0 0 3px rgba(191, 184, 173, 0.15),
0 2px 6px rgba(80, 55, 35, 0.08) !important;
  border-radius:0 15px 0 15px!important ;
}


/* ====按钮图标类==== */
.inline-drawer-icon {
    font-size: 0 !important;  
    position: relative !important;
    display: inline-block !important; 
    transition: all 0.3s ease !important;
    cursor: pointer !important;
  margin: 3px  25px;
}


.inline-drawer-icon::before {
    content: "" !important; 
  background: url('https://iili.io/B4Hz3SR.png') center/contain no-repeat !important;
  font-family: inherit !important;
  font-size: 15px !important;
  width: 15px; 
  height: 15px; 
  display: inline-block; 
}


.qr--button,
.menu_button {
    background: linear-gradient(135deg, #FFFDF9 0%, #FDF9F0 100%) !important;
    color: #B49B6F !important;
    padding: 4px px !important;
    border: 1px solid #E8DDD0 !important;
    outline: 2px solid #FFFFFF !important;
    outline-offset: -1px !important;
    box-shadow: 0 6px 12px -6px rgba(120, 80, 50, 0.12), inset 0 1px 0 rgba(255, 255, 245, 0.8) !important;
    font-weight: 500 !important;
    font-size: 0.95em !important;
    letter-spacing: 0.03em !important;
    border-radius: 0 !important;
    transition: all 0.25s ease-out !important;
    cursor: pointer !important;
    position: relative !important;
    overflow: hidden !important;
    backdrop-filter: blur(2px) !important;
}

.qr--button:hover,
.menu_button:hover {
    background: linear-gradient(135deg, #FFFFFF 0%, #FFF8ED 100%) !important;
    color: #9E7B4F !important;
    border-color: #DCCFBC !important;
    box-shadow: 0 10px 18px -8px rgba(80, 50, 25, 0.2), inset 0 1px 0 rgba(255, 255, 240, 1) !important;
    transform: translateY(-1px) scale(1.02) !important;
}

.qr--button:active,
.menu_button:active {
    transform: translateY(1px) scale(0.98) !important;
    box-shadow: 0 2px 5px -2px rgba(80, 50, 25, 0.2) !important;
    filter: brightness(0.97) !important;
    transition: all 0.05s linear !important;
}


.menu_button.redWarningBG,
.menu_button.red_button {
    color:  rgba(138, 48, 48, 1) !important;
}
.menu_button.world_set,
.menu_button.fav_on {
   color: rgba(255, 232, 97, 1) !important;
}
/*======复选框======*/

input[type="checkbox"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    background:white;
width: 15px !important;
    height: 15px !important;
    box-shadow: none !important;
    border: none !important;
    cursor: pointer !important;
    outline: none !important;
border-radius: 50%;
    }

input[type="checkbox"]:checked {
    background: url('https://iili.io/B4Hz3SR.png') no-repeat center/contain !important;
    box-shadow: none !important;
width: 15px !important;
    height: 15px !important;
    border: none !important;
  opacity: 1!important;
    }

input[type="checkbox"]::before, 
input[type="checkbox"]::after {
    display: none !important;
    content: none !important;
}


/*感谢nakari老师的防误触*/
@media screen and (max-width: 768px) {
  /* 禁用标签交互 */
  #user-settings-block .checkbox_label {
    pointer-events: none !important;
  }
  /* 恢复复选框交互 */
  #user-settings-block input[type="checkbox"] {
    pointer-events: auto !important;
  }
}
/* =====滚动条和滑动条=====*/
/* 隐藏所有滚动条 */
::-webkit-scrollbar {
  display: none !important;
}
/* Firefox */
* {
  scrollbar-width: none !important;
}
/* 滑动条 */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 90%;
  height: 1px!important;
  background: linear-gradient(to right, rgba(255, 255, 255, 1), rgba(255, 255, 255, 1)) !important; 
  border-radius: 0;
  outline: none;
  margin: 10px 0;
}

/* 滑块按钮 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 55px !important;
    height: 55px !important;
    background: url('https://iili.io/B4fnmnp.png') center/contain no-repeat !important; 
    border: none;
    cursor: pointer; 
  filter: drop-shadow(-2px 2px 2px rgba(0, 0, 0, 0.2)); 
}
input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

/* ====角色和用户区域==== */
/* 感谢twelve老师的收藏区左右滑动 */
#HotSwapWrapper {
    overflow: hidden;
}
#HotSwapWrapper > div {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    height: calc(var(--avatar-base-height) + 10px);
    &::-webkit-scrollbar { height: 5px }
    &::-webkit-scrollbar-thumb {
        background: var(--ui-color-sec);
        border-radius: 5px;
    }
}
body.big-avatars #HotSwapWrapper > div {
    height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}

.avatar-container.interactable.selected {
 background-color: rgba(250, 249, 246, 1) !important;
  overflow: visible !important;
    background-image :none  !important;
    border: 3px solid rgba(255, 255, 255, 1) !important;
    border-radius: 0 !important;
  padding: 10px !important; 
  margin: 9px 0 !important;
  position: relative !important; 
  min-height: 40px !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1) !important;
}

.avatar-container.interactable.selected::after {
    content: "";
    position: absolute;
    top: -33px;
    right: -12px;
    width: 75px;
    height: 75px;
    background: url('https://iili.io/B4fnmnp.png') center/contain no-repeat;
    transform: scaleX(-1) rotate(-15deg); 
    z-index: 100;
    pointer-events: none;
    filter: drop-shadow(-2px 2px 2px rgba(0, 0, 0, 0.1)); 
}
.character_select.is_fav:hover,
.avatar-container.interactable.selected:hover {
    transform: scale(1.05);
    box-shadow: 0 10px 20px rgba(137, 127, 94, 0.6) !important;
}

.character_select.is_fav .ch_name {
color: var(--SmartThemeBorderColor)!important;
}

.character_select.is_fav .avatar {
    position: relative;
  outline: none !important;  
    margin-top: 6px;
  padding: 1px;
}

.character_select.is_fav .avatar::before {
    content: "";
    position: absolute;
    top: -15px;
    left: -13px;
    width: 50px;
    height: 50px;
    background: url('https://iili.io/B4fnmnp.png') center/contain no-repeat;
    transform: rotate(-35deg);
    z-index: 100;
    pointer-events: none;
    filter: drop-shadow(2px 2px 2px rgba(0, 0, 0, 0.2));
  overflow: visible !important;
  z-index: 999;
overflow: visible !important;
}




/*角色区域*/
/*布局灵感来自kakaa老师的双色盒子*/
/* 重新布局容器 */
#avatar_div.avatar_div.buttons_block.alignitemsflexstart.justifySpaceBetween.flexnowrap {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    position: relative !important;

}
/* 角色头像 */
img#avatar_load_preview {
    position: relative !important;
    margin: 0 !important;    
    width: 70% !important; 
  height: auto !important; 
  aspect-ratio: 1.7/ 1.1!important; 
    transform: rotate(0deg) !important;
  border: 1px solid rgba(125, 109, 69, 1) !important;   box-shadow: 0 0 0 3px rgba(255, 255, 255, 1), 0 0 5px rgba(0, 0, 0, 0.88);
  border-radius: 0;

 } 
/* 控制按钮 */
div#avatar_controls.flex-container {
    order: 2 !important;
    width: auto !important; 
    max-width: 100% !important;
    display: flex !important;
    justify-content: center !important;
    gap: 10px !important;
    margin: 1px auto !important; 
    position: relative !important;
    left: 0 !important;
    right: 0 !important;

}

/* =====预设部分===== */
ul#completion_prompt_manager_list.text_pole.ui-sortable {
background: none !important;
  border: none!important;
}
/* 已开启的提示词条目 */
.completion_prompt_manager_prompt {
  background-color: rgba(250, 249, 246, 1) !important;
    background-image :none  !important;
    border: 3px solid rgba(255, 255, 255, 1) !important;
    border-radius: 0 !important;
  padding: 10px 25px 10px 45px !important; 
  margin: 9px 0 !important;
  position: relative !important; 
  min-height: 40px !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1) !important;
}
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled)::before {
  content: '';
  position: absolute;
  left: -19px; 
  top: 10%;
  transform: translateY(-50%)rotate(-30deg);
  width: 70px; 
  height: 70px; 
  background: url('https://iili.io/B4fnmnp.png') center/contain no-repeat !important;
  pointer-events: none !important;
  z-index: 10;
  filter: drop-shadow(-2px 2px 2px rgba(0, 0, 0, 0.1));
}
/* 未开启的提示词条目 */
.completion_prompt_manager_prompt_disabled {
  background-color: rgba(255, 255, 255, 1)!important;   
    border: 2px solid rgba(255, 255, 255, 1) !important;  
  color: rgba(136, 136, 136, 1) !important; 
  opacity: 0.7 !important; 
}

/* =====七七八八框框===== */
.height100p.wide100p.maximized_textarea {
background: transparent;
}
textarea:not(.height100p.wide100p.maximized_textarea, .popup-input.text_pole.result-control.auto-select,#send_textarea),
input[type="number"],
select {
background: rgba(255, 254, 250, 1) !important;
border: 1px solid #E6DBCB !important;
outline: 1px solid #FFFFFF !important;
outline-offset: 1px !important;
box-shadow: inset 0 1px 2px rgba(100, 70, 40, 0.04), 0 2px 6px rgba(100, 70, 40, 0.06) !important;
display: inline-block !important;
padding: 6px 8px !important;
margin: 5px 2px !important;
border-radius: 0px !important;
text-align: left !important;
line-height: normal !important;
vertical-align: middle !important;
color: #8B7355 !important;
transition: all 0.2s ease !important;
}

.text_pole {
background: linear-gradient(135deg, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 100%) !important;
border-radius: 0px !important;
color: rgba(141, 127, 113, 1) !important;
padding: 6px 4px !important;
border: 1px solid #E8DCC8 !important;
box-shadow: inset 0 1px 0 #FFFFFF, 0 4px 12px rgba(80, 55, 35, 0.08) !important;

}

.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
position: relative;
border: 1px solid rgba(219, 210, 194, 1) !important;
box-shadow: 0 2px 8px rgba(80, 55, 35, 0.08), inset 0 1px 0 #FFFFFF !important;
border-radius: 0px !important;
background: linear-gradient(135deg, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 100%) !important;
color: #A0815C !important;
z-index: 1;
text-align: center !important;
line-height: normal !important;
vertical-align: middle !important;
font-weight: 500 !important;
letter-spacing: 0.5px !important;
}

#user-settings-block h4 {
position: relative;
padding: 5px 8px !important;
margin: 0 !important;
